package com.mengzhihua.crm;
import com.mengzhihua.crm.common.*;import com.mengzhihua.crm.sales.entity.*;import com.mengzhihua.crm.sales.repository.*;import com.mengzhihua.crm.service.entity.*;import com.mengzhihua.crm.service.service.*;import org.springframework.boot.*;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Component;import java.math.*;import java.time.*;
@Component @Profile("!test") public class DataInitializer implements CommandLineRunner{private final AccountRepository accounts;private final LeadRepository leads;private final OpportunityRepository opps;private final CaseService cases;private final KnowledgeService knowledge;public DataInitializer(AccountRepository a,LeadRepository l,OpportunityRepository o,CaseService c,KnowledgeService k){accounts=a;leads=l;opps=o;cases=c;knowledge=k;}public void run(String... args){if(accounts.count()>0)return;for(int i=1;i<=8;i++){Account a=new Account();a.setName("演示客户"+i);a.setIndustry(i%2==0?"制造业":"互联网");a.setType(i%3==0?Enums.AccountType.CUSTOMER:Enums.AccountType.PROSPECT);a.setLevel(i%3==0?Enums.AccountLevel.A:Enums.AccountLevel.B);accounts.save(a);}for(int i=1;i<=12;i++){Lead l=new Lead();l.setName("演示线索"+i);l.setCompany("潜在企业"+i);l.setSource(Enums.LeadSource.values()[i%6]);l.setStatus(Enums.LeadStatus.values()[i%4]);l.setRating(Enums.Rating.values()[i%3]);leads.save(l);}for(int i=1;i<=10;i++){Opportunity o=new Opportunity();o.setName("演示商机"+i);o.setAmount(new BigDecimal(i*10000));o.setStage(Enums.OpportunityStage.values()[i%6]);o.setProbability(o.getStage().getProbability());o.setExpectedCloseDate(LocalDate.now().plusDays(i*5));opps.save(o);}for(int i=1;i<=15;i++){CrmCase c=new CrmCase();c.setSubject("演示服务工单"+i);c.setPriority(Enums.CasePriority.values()[i%4]);c.setStatus(Enums.CaseStatus.values()[i%6]);if(i<3)c.setSlaDueAt(LocalDateTime.now().minusHours(2));cases.save(c);}for(int i=1;i<=6;i++){KnowledgeArticle k=new KnowledgeArticle();k.setTitle("客户服务知识"+i);k.setCategory("常见问题");k.setKeywords("服务,帮助");k.setContent("这是演示知识文章内容。");k.setStatus(i<5?Enums.ArticleStatus.PUBLISHED:Enums.ArticleStatus.DRAFT);knowledge.save(k);}}}
